automations = env['base.automation'].search([])
for automation in automations:
    model_name = automation.model_id.model
    try:
        if 'company_id' in env[model_name]._fields:
            sample_record = env[model_name].search([], limit=1)
            if sample_record and sample_record.company_id:
                automation.company_id = sample_record.company_id
            else:
                automation.company_id = env.company
        else:
            automation.company_id = False
    except Exception as e:
        automation.company_id = env.company
env.cr.commit()
